param([Parameter(Mandatory)][string]$OutputPath)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
$assembly=[Reflection.Emit.AssemblyBuilder]::DefineDynamicAssembly([Reflection.AssemblyName]::new('FallbackEqualityOracle'),[Reflection.Emit.AssemblyBuilderAccess]::Run);$module=$assembly.DefineDynamicModule('FallbackEqualityOracle')
function Bump($il,$field){$il.Emit([Reflection.Emit.OpCodes]::Ldsfld,$field);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_1);$il.Emit([Reflection.Emit.OpCodes]::Add);$il.Emit([Reflection.Emit.OpCodes]::Stsfld,$field)}
function ThrowMode($il,$mode,[int]$value){$next=$il.DefineLabel();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$mode);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4,$value);$il.Emit([Reflection.Emit.OpCodes]::Bne_Un,$next);$il.Emit([Reflection.Emit.OpCodes]::Ldstr,'fallback method failure');$il.Emit([Reflection.Emit.OpCodes]::Newobj,[InvalidOperationException].GetConstructor([type[]]@([string])));$il.Emit([Reflection.Emit.OpCodes]::Throw);$il.MarkLabel($next)}
function CustomType([string]$Direction){
 $base=[type]("System.Text.${Direction}Fallback");$buffer=[type]("System.Text.${Direction}FallbackBuffer");$replacement=[type]("System.Text.${Direction}ReplacementFallback");$builder=$module.DefineType('Custom'+$Direction,[Reflection.TypeAttributes]::Public,$base);[void]$builder.DefineDefaultConstructor([Reflection.MethodAttributes]::Public);$key=$builder.DefineField('Key',[int],[Reflection.FieldAttributes]::Public);$mode=$builder.DefineField('Mode',[int],[Reflection.FieldAttributes]::Public);$hash=$builder.DefineField('Hash',[int],[Reflection.FieldAttributes]::Public);$eqCalls=$builder.DefineField('EqualsCalls',[int],[Reflection.FieldAttributes]'Public,Static');$hashCalls=$builder.DefineField('HashCalls',[int],[Reflection.FieldAttributes]'Public,Static');$attrs=[Reflection.MethodAttributes]'Public,Virtual,HideBySig'
 $m=$builder.DefineMethod('get_MaxCharCount',$attrs-bor[Reflection.MethodAttributes]::SpecialName,[int],[type[]]@());$il=$m.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_1);$il.Emit([Reflection.Emit.OpCodes]::Ret);$builder.DefineMethodOverride($m,$base.GetProperty('MaxCharCount').GetMethod)
 $m=$builder.DefineMethod('CreateFallbackBuffer',$attrs,$buffer,[type[]]@());$il=$m.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Newobj,$replacement.GetConstructor([type[]]@()));$il.Emit([Reflection.Emit.OpCodes]::Callvirt,$base.GetMethod('CreateFallbackBuffer'));$il.Emit([Reflection.Emit.OpCodes]::Ret);$builder.DefineMethodOverride($m,$base.GetMethod('CreateFallbackBuffer'))
 $m=$builder.DefineMethod('GetHashCode',$attrs,[int],[type[]]@());$il=$m.GetILGenerator();Bump $il $hashCalls;ThrowMode $il $mode 4;$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$hash);$il.Emit([Reflection.Emit.OpCodes]::Ret);$builder.DefineMethodOverride($m,[object].GetMethod('GetHashCode'))
 $m=$builder.DefineMethod('Equals',$attrs,[bool],[type[]]@([object]));$il=$m.GetILGenerator();Bump $il $eqCalls;ThrowMode $il $mode 3;$keyCase=$il.DefineLabel();$yes=$il.DefineLabel();$no=$il.DefineLabel();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$mode);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_1);$il.Emit([Reflection.Emit.OpCodes]::Beq,$no);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$mode);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_2);$il.Emit([Reflection.Emit.OpCodes]::Beq,$yes)
 $other=$il.DeclareLocal($builder);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_1);$il.Emit([Reflection.Emit.OpCodes]::Isinst,$builder);$il.Emit([Reflection.Emit.OpCodes]::Stloc,$other);$il.Emit([Reflection.Emit.OpCodes]::Ldloc,$other);$il.Emit([Reflection.Emit.OpCodes]::Brfalse,$no);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$key);$il.Emit([Reflection.Emit.OpCodes]::Ldloc,$other);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$key);$il.Emit([Reflection.Emit.OpCodes]::Ceq);$il.Emit([Reflection.Emit.OpCodes]::Ret);$il.MarkLabel($yes);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_1);$il.Emit([Reflection.Emit.OpCodes]::Ret);$il.MarkLabel($no);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_0);$il.Emit([Reflection.Emit.OpCodes]::Ret);$builder.DefineMethodOverride($m,[object].GetMethod('Equals',[type[]]@([object])));return $builder.CreateType()
}
$encoderType=CustomType 'Encoder';$decoderType=CustomType 'Decoder';$values=[Collections.Generic.List[Text.Encoding]]::new();$profiles=@()
foreach($emit in @($false,$true)){foreach($key in @(1,2)){foreach($mode in 0..4){foreach($selection in @('Encoder','Decoder','Both')){
 $e=[Text.Encoding]([Text.UTF8Encoding]::new($emit)).Clone();foreach($direction in @('Encoder','Decoder')){if($selection -eq $direction -or $selection -eq 'Both'){$type=if($direction -eq 'Encoder'){$encoderType}else{$decoderType};$fallback=[Activator]::CreateInstance($type);$type.GetField('Key').SetValue($fallback,$key);$type.GetField('Mode').SetValue($fallback,$mode);$type.GetField('Hash').SetValue($fallback,[int](1000*$key+$(if($direction -eq 'Encoder'){17}else{29})));$e.($direction+'Fallback')=$fallback}};$values.Add($e);$profiles+=[ordered]@{emit=$emit;key=$key;mode=$mode;selection=$selection}
}}}}
foreach($emit in @($false,$true)){foreach($strict in @($false,$true)){$values.Add([Text.UTF8Encoding]::new($emit,$strict));$profiles+=[ordered]@{emit=$emit;key=0;mode=0;selection='Predefined';strict=$strict}}}
foreach($throwCodePage in @($false,$true)){
 $builder=$module.DefineType('CodePage'+$throwCodePage,[Reflection.TypeAttributes]::Public,[Text.UTF8Encoding]);[void]$builder.DefineDefaultConstructor([Reflection.MethodAttributes]::Public);$getter=$builder.DefineMethod('get_CodePage',[Reflection.MethodAttributes]'Public,Virtual,HideBySig,SpecialName',[int],[type[]]@());$il=$getter.GetILGenerator();if($throwCodePage){$il.Emit([Reflection.Emit.OpCodes]::Ldstr,'CodePage must not be called');$il.Emit([Reflection.Emit.OpCodes]::Newobj,[InvalidOperationException].GetConstructor([type[]]@([string])));$il.Emit([Reflection.Emit.OpCodes]::Throw)}else{$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4,90000);$il.Emit([Reflection.Emit.OpCodes]::Ret)};$builder.DefineMethodOverride($getter,[Text.Encoding].GetProperty('CodePage').GetMethod);$values.Add([Activator]::CreateInstance($builder.CreateType()));$profiles+=[ordered]@{emit=$false;key=0;mode=0;selection=$(if($throwCodePage){'CodePageThrows'}else{'CodePageOverride'});strict=$false}
}
function ResetCounts{foreach($type in @($encoderType,$decoderType)){foreach($name in @('EqualsCalls','HashCalls')){$type.GetField($name).SetValue($null,0)}}}
function Counts{return ,@(foreach($type in @($encoderType,$decoderType)){foreach($name in @('EqualsCalls','HashCalls')){[int]$type.GetField($name).GetValue($null)}})}
function Failure($e){while(($e -is [Management.Automation.RuntimeException] -or $e -is [Reflection.TargetInvocationException]) -and $null -ne $e.InnerException){$e=$e.InnerException};return [ordered]@{ok=$false;exception=$e.GetType().FullName;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})}}
$rows=@();foreach($left in 0..($values.Count-1)){foreach($right in -3..($values.Count-1)){ResetCounts;$target=$null;if($right -eq -2){$target='UTF-8'}elseif($right -eq -1){$target=[object]::new()}elseif($right -ge 0){$target=$values[$right]};try{$result=[ordered]@{ok=$true;equals=$values[$left].Equals($target)}}catch{$result=Failure $_.Exception};$rows+=[ordered]@{left=$left;right=$right;result=$result;calls=Counts}}
 ResetCounts;$hashCalls=$null;try{$hash=$values[$left].GetHashCode();$hashCalls=Counts;$sum=([long]$values[$left].EncoderFallback.GetHashCode()+[long]$values[$left].DecoderFallback.GetHashCode()+65001+[int]$profiles[$left].emit)-band 0xffffffffL;if($sum -ge 2147483648L){$sum-=4294967296L};$result=[ordered]@{ok=$true;hashFormulaMatches=$hash -eq $sum}}catch{$result=Failure $_.Exception};if($null -eq $hashCalls){$hashCalls=Counts};$profiles[$left].hashResult=$result;$profiles[$left].hashCalls=$hashCalls
}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();profiles=$profiles;rows=$rows;qualification='SELECTED_CUSTOM_FALLBACK_EQUALITY_HASH_DISPATCH_AND_CALL_COUNTS_ONLY; NO_RAW_CROSS_PROCESS_HASH_EQUALITY_FULL_METADATA_SOURCE_ABI_OR_TASK_ACCEPTANCE'}
[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 11)+"`n",[Text.UTF8Encoding]::new($false));Write-Output 'PASS pinned custom fallback equality/hash dispatch: 66 profiles and 4554 comparisons'
